<script setup>
import { $api } from '@/utils/api'
const data=ref({bookings:[],corrections:[],emergencies:[],notifications:[],report:{}});const busy=ref(false);const error=ref('');const tab=ref('dashboard');const selected=ref(null);const correction=reactive({action:'mark_late',reason:'',idempotency_key:''});const emergency=reactive({scope_type:'all_temporary',scope_id:null,reason:'',idempotency_key:''})
const label=v=>(v||'').replaceAll('_',' ');async function load(){busy.value=true;try{data.value=await $api('/check-in-operations')}catch(e){error.value=e?.data?.message||'Check-in operations could not be loaded.'}finally{busy.value=false}}async function mutate(url,body){busy.value=true;error.value='';try{await $api(url,{method:'POST',body});selected.value=null;await load()}catch(e){error.value=e?.data?.message||Object.values(e?.data?.errors||{}).flat()[0]||'The operation could not be completed.'}finally{busy.value=false}}function openCorrection(a){selected.value=a;correction.reason='';correction.idempotency_key=crypto.randomUUID()}function correct(){mutate(`/attendance/${selected.value.id}/corrections`,correction)}function suspend(){emergency.idempotency_key=crypto.randomUUID();mutate('/access/emergency-suspensions',emergency)}onMounted(load)
</script>
<template><div><div class="d-flex flex-wrap justify-space-between align-center gap-3 mb-6"><div><h3 class="text-h3">Check-in & temporary access</h3><p class="text-medium-emphasis">Attendance, no-shows, dry-run access, emergency controls and privacy-safe reporting.</p></div><VBtn :loading="busy" variant="tonal" @click="load">Refresh</VBtn></div><VAlert v-if="error" type="error" class="mb-4">{{error}}</VAlert><VRow class="mb-4"><VCol v-for="(v,k) in data.report" :key="k" cols="6" md="3"><VCard><VCardText><div class="text-caption">{{label(k)}}</div><div class="text-h4">{{v}}</div></VCardText></VCard></VCol></VRow><VTabs v-model="tab" class="mb-4"><VTab value="dashboard">Attendance</VTab><VTab value="access">Access</VTab><VTab value="emergency">Emergency</VTab><VTab value="history">History</VTab></VTabs><VWindow v-model="tab"><VWindowItem value="dashboard"><VCard><VCardTitle>Check-in dashboard & no-show queue</VCardTitle><div class="table-wrap"><VTable><thead><tr><th>Booking</th><th>Facility / sport</th><th>Member</th><th>Window</th><th>Attendance</th><th>Access</th><th/></tr></thead><tbody><tr v-for="b in data.bookings" :key="b.id"><td>{{b.booking_reference}}<br><small>{{new Date(b.starts_at).toLocaleString()}}</small></td><td>{{b.facility?.name}}<br><small>#{{b.sport_code_id}}</small></td><td>{{b.member?.first_name}} {{b.member?.last_name}}</td><td><small>{{b.attendance?new Date(b.attendance.check_in_opens_at).toLocaleString():'—'}}<br>{{b.attendance?new Date(b.attendance.check_in_closes_at).toLocaleString():'—'}}</small></td><td>{{label(b.attendance?.status)}}</td><td>{{b.access_grants?.map(g=>label(g.status)).join(', ')||'none'}}</td><td><VBtn v-if="b.attendance" size="small" variant="tonal" @click="openCorrection(b.attendance)">Correct</VBtn></td></tr></tbody></VTable></div></VCard></VWindowItem><VWindowItem value="access"><VCard><VCardTitle>Temporary access grants</VCardTitle><VCardText><div v-for="b in data.bookings" :key="b.id"><VChip v-for="g in b.access_grants" :key="g.id" class="ma-1">{{b.booking_reference}} · {{g.zone?.name}} · {{label(g.status)}} · {{new Date(g.valid_from).toLocaleString()}}–{{new Date(g.valid_until).toLocaleString()}}</VChip></div></VCardText></VCard></VWindowItem><VWindowItem value="emergency"><VCard><VCardTitle>Emergency temporary-access suspension</VCardTitle><VCardText><VSelect v-model="emergency.scope_type" :items="['all_temporary','sport_code','venue','zone','endpoint']" label="Scope"/><VTextField v-if="emergency.scope_type!=='all_temporary'" v-model.number="emergency.scope_id" type="number" label="Scope ID"/><VTextarea v-model="emergency.reason" label="Reason"/><VAlert type="warning" variant="tonal" class="mb-3">This affects temporary booking access only. It never changes permanent member access or finances.</VAlert><VBtn color="error" :disabled="emergency.reason.length<8" @click="suspend">Confirm suspension</VBtn><VDivider class="my-4"/><div v-for="e in data.emergencies" :key="e.id">{{label(e.scope_type)}} · {{label(e.status)}} · {{e.affected_grants}} grants <VBtn v-if="e.status==='active'" size="small" variant="tonal" @click="mutate(`/access/emergency-suspensions/${e.id}/restore`,{reason:'Authorized operational restoration'})">Restore</VBtn></div></VCardText></VCard></VWindowItem><VWindowItem value="history"><VCard><VCardTitle>Correction & notification history</VCardTitle><VCardText><div v-for="c in data.corrections" :key="c.id">{{label(c.action)}} · {{c.reason}}</div><VDivider class="my-3"/><div v-for="n in data.notifications" :key="n.id">{{label(n.event_type)}} · {{n.created_at}}</div></VCardText></VCard></VWindowItem></VWindow><VDialog :model-value="!!selected" max-width="560" @update:model-value="v=>!v&&(selected=null)"><VCard><VCardTitle>Correct attendance</VCardTitle><VCardText><VSelect v-model="correction.action" :items="['reverse_check_in','mark_late','mark_no_show','reverse_no_show','excuse_absence','release_court','keep_reserved']" label="Action"/><VTextarea v-model="correction.reason" label="Required reason"/><VAlert type="info" variant="tonal">The previous state remains in immutable correction and audit history.</VAlert></VCardText><VCardActions><VSpacer/><VBtn variant="tonal" @click="selected=null">Cancel</VBtn><VBtn :disabled="correction.reason.length<5" @click="correct">Confirm correction</VBtn></VCardActions></VCard></VDialog></div></template>
<style scoped>.table-wrap{overflow-x:auto}</style>
